create extension if not exists "pgcrypto";

create table if not exists public.clubs (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, short_name text, logo_url text, city text, state text, founded_year int, stadium text, description text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.national_teams (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, team_type text not null default 'senior', gender text not null default 'men', logo_url text, fifa_ranking int, coach text, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.players (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, club_id uuid references public.clubs(id) on delete set null, national_team_id uuid references public.national_teams(id) on delete set null, position text, shirt_number int, date_of_birth date, nationality text default 'Indian', photo_url text, appearances int not null default 0, goals int not null default 0, assists int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.leaderboard (id uuid primary key default gen_random_uuid(), club_id uuid not null references public.clubs(id) on delete cascade, season text not null, played int not null default 0, won int not null default 0, drawn int not null default 0, lost int not null default 0, goals_for int not null default 0, goals_against int not null default 0, goal_difference int generated always as (goals_for-goals_against) stored, points int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(club_id,season));

create table if not exists public.blog_topics (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, created_at timestamptz not null default now());
create table if not exists public.blogs (id uuid primary key default gen_random_uuid(), author_id text not null references public.fan_profiles(user_id) on delete cascade, topic_id uuid references public.blog_topics(id) on delete set null, title text not null, slug text not null unique, excerpt text, content text not null, cover_image_url text, status text not null default 'draft' check(status in ('draft','pending','published','rejected','archived')), moderation_note text, view_count int not null default 0, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.comments (id uuid primary key default gen_random_uuid(), blog_id uuid not null references public.blogs(id) on delete cascade, user_id text not null references public.fan_profiles(user_id) on delete cascade, parent_id uuid references public.comments(id) on delete cascade, content text not null, is_hidden boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.likes (id uuid primary key default gen_random_uuid(), blog_id uuid not null references public.blogs(id) on delete cascade, user_id text not null references public.fan_profiles(user_id) on delete cascade, created_at timestamptz not null default now(), unique(blog_id,user_id));

create table if not exists public.product_categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, created_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), category_id uuid references public.product_categories(id) on delete set null, name text not null, slug text not null unique, description text, sku text unique, price numeric(12,2) not null check(price>=0), compare_at_price numeric(12,2), stock_quantity int not null default 0 check(stock_quantity>=0), image_url text, images text[] not null default '{}', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.cart_items (id uuid primary key default gen_random_uuid(), user_id text not null references public.fan_profiles(user_id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, quantity int not null check(quantity>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,product_id));
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_number text not null unique, user_id text not null references public.fan_profiles(user_id), status text not null default 'pending' check(status in ('pending','confirmed','processing','shipped','delivered','cancelled','refunded')), payment_status text not null default 'pending' check(payment_status in ('pending','paid','failed','refunded')), subtotal numeric(12,2) not null, shipping_amount numeric(12,2) not null default 0, total_amount numeric(12,2) not null, shipping_address jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), product_name text not null, unit_price numeric(12,2) not null, quantity int not null check(quantity>0), total_price numeric(12,2) not null);
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), user_id text not null references public.fan_profiles(user_id), gateway_order_id text not null unique, gateway_payment_id text unique, signature text, amount numeric(12,2) not null, status text not null default 'created', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id text not null references public.fan_profiles(user_id) on delete cascade, type text not null, title text not null, message text not null, data jsonb not null default '{}', is_read boolean not null default false, read_at timestamptz, created_at timestamptz not null default now());

create index if not exists idx_blogs_status_created on public.blogs(status,created_at desc); create index if not exists idx_comments_blog on public.comments(blog_id,created_at); create index if not exists idx_products_category on public.products(category_id); create index if not exists idx_orders_user on public.orders(user_id,created_at desc); create index if not exists idx_notifications_user_unread on public.notifications(user_id,is_read,created_at desc);

create or replace function public.increment_blog_views(blog_id uuid) returns void language sql security definer as $$ update public.blogs set view_count=view_count+1 where id=blog_id $$;
create or replace function public.create_order_from_cart(p_user_id text,p_shipping_address jsonb) returns uuid language plpgsql security definer as $$ declare v_order uuid;v_subtotal numeric;v_item record; begin select sum(c.quantity*p.price) into v_subtotal from public.cart_items c join public.products p on p.id=c.product_id where c.user_id=p_user_id and p.is_active and p.stock_quantity>=c.quantity; if v_subtotal is null then raise exception 'Cart is empty or contains unavailable products';end if; insert into public.orders(order_number,user_id,subtotal,total_amount,shipping_address) values('IFC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)),p_user_id,v_subtotal,v_subtotal,p_shipping_address) returning id into v_order; for v_item in select c.product_id,c.quantity,p.name,p.price,p.stock_quantity from public.cart_items c join public.products p on p.id=c.product_id where c.user_id=p_user_id for update of p loop if v_item.stock_quantity<v_item.quantity then raise exception 'Insufficient stock for %',v_item.name;end if;insert into public.order_items(order_id,product_id,product_name,unit_price,quantity,total_price)values(v_order,v_item.product_id,v_item.name,v_item.price,v_item.quantity,v_item.price*v_item.quantity);update public.products set stock_quantity=stock_quantity-v_item.quantity where id=v_item.product_id;end loop;delete from public.cart_items where user_id=p_user_id;return v_order;end $$;
create or replace function public.mark_order_paid(p_user_id text,p_gateway_order_id text,p_gateway_payment_id text,p_signature text) returns jsonb language plpgsql security definer as $$ declare v_payment public.payments; begin update public.payments set gateway_payment_id=p_gateway_payment_id,signature=p_signature,status='paid',updated_at=now() where gateway_order_id=p_gateway_order_id and user_id=p_user_id and status<>'paid' returning * into v_payment;if v_payment.id is null then raise exception 'Payment not found or already processed';end if;update public.orders set payment_status='paid',status='confirmed',updated_at=now() where id=v_payment.order_id;insert into public.notifications(user_id,type,title,message,data)values(p_user_id,'order','Payment successful','Your order has been confirmed',jsonb_build_object('orderId',v_payment.order_id));return jsonb_build_object('verified',true,'orderId',v_payment.order_id);end $$;
